-- Calibrated synthetic fleet history (see docs/superpowers/specs/2026-11-23-calibrated-fleet-design.md).
-- Applied once by /migrate.sh. Seed files are generated by research/generate_fleet.py.
\set manifest `cat /seed/fleet_v2/manifest.json`
BEGIN;

INSERT INTO source_records VALUES
 ('demo-identities-v2', 'synthetic', '2026-11-23T00:00:00Z',
  'Fictional identities v2: lead-acid when index divisible by 5, otherwise LFP; rated energy 16 + 4 × (index mod 8) kWh.'),
 ('demo-inspection-v2', 'synthetic', '2026-11-23T00:00:00Z',
  'Chemistry model-sheet entries updated to match fictional identities v2.'),
 ('demo-fleet-v2', 'synthetic', '2026-11-23T00:00:00Z',
  'Synthetic daily pack history ' || (:'manifest'::jsonb ->> 'generator_version') || ', calibrated with '
  || (:'manifest'::jsonb ->> 'calibration_version') || ' from public HUST and Aalborg LFP measurements. Seed digest '
  || (:'manifest'::jsonb ->> 'digest') || '.')
ON CONFLICT DO NOTHING;

UPDATE batteries
SET chemistry = CASE WHEN substr(battery_id, 10)::int % 5 = 0 THEN 'lead-acid' ELSE 'LFP' END,
    source_id = 'demo-identities-v2'
WHERE source_id = 'demo-identities-v1';

UPDATE passport_fields f
SET value_text = b.chemistry, source_id = 'demo-inspection-v2'
FROM batteries b
WHERE f.battery_id = b.battery_id AND f.field_code = 'chemistry' AND f.value_text <> b.chemistry;

DROP TABLE IF EXISTS vehicle_assignments, charge_sessions, telemetry_samples, service_events;

CREATE TABLE fleet_seed_manifest (
 generator_version text NOT NULL, calibration_version text NOT NULL, seed bigint NOT NULL,
 digest text PRIMARY KEY, manifest jsonb NOT NULL,
 source_id text NOT NULL REFERENCES source_records
);
INSERT INTO fleet_seed_manifest
SELECT m ->> 'generator_version', m ->> 'calibration_version', (m ->> 'seed')::bigint, m ->> 'digest', m,
       'demo-fleet-v2'
FROM (SELECT :'manifest'::jsonb AS m) x;

CREATE TABLE fleet_sites (
 site_id text PRIMARY KEY, name text NOT NULL, ambient_mean_c real NOT NULL, seasonal_amp_c real NOT NULL,
 source_id text NOT NULL REFERENCES source_records
);
CREATE TABLE pack_profiles (
 battery_id text PRIMARY KEY REFERENCES batteries, site_id text NOT NULL REFERENCES fleet_sites,
 commissioned_on date NOT NULL, shifts int NOT NULL, life_multiplier real NOT NULL,
 opportunity_propensity real NOT NULL, efc_before_window real NOT NULL,
 source_id text NOT NULL REFERENCES source_records
);
CREATE TABLE pack_daily (
 battery_id text REFERENCES batteries, day date, efc real NOT NULL, throughput_kwh real NOT NULL,
 soc_min_pct real NOT NULL, soc_max_pct real NOT NULL, temp_mean_c real NOT NULL, temp_max_c real NOT NULL,
 charge_sessions int NOT NULL, opportunity_charges int NOT NULL, capacity_pct real, resistance_pct real,
 temp_regime text NOT NULL CHECK (temp_regime IN
   ('calibrated','extrapolated_below_calibrated_range','clamped_low','clamped_high')),
 source_id text NOT NULL REFERENCES source_records, PRIMARY KEY (battery_id, day)
);
CREATE TABLE pack_monthly_histograms (
 battery_id text REFERENCES batteries, month date, kind text CHECK (kind IN ('temperature','soc')),
 bin_lower real, bin_upper real NOT NULL, hours real NOT NULL,
 source_id text NOT NULL REFERENCES source_records, PRIMARY KEY (battery_id, month, kind, bin_lower)
);
CREATE TABLE pack_events (
 battery_id text REFERENCES batteries, observed_at timestamptz, kind text, detail text NOT NULL,
 source_id text NOT NULL REFERENCES source_records, PRIMARY KEY (battery_id, observed_at, kind)
);

CREATE TEMP TABLE s_sites (site_id text, name text, ambient_mean_c real, seasonal_amp_c real) ON COMMIT DROP;
CREATE TEMP TABLE s_profiles (battery_id text, chemistry text, rated_kwh int, site_id text, commissioned_on date,
 shifts int, life_multiplier real, opportunity_propensity real, efc_before_window real) ON COMMIT DROP;
CREATE TEMP TABLE s_daily (LIKE pack_daily) ON COMMIT DROP;
ALTER TABLE s_daily DROP COLUMN source_id;
CREATE TEMP TABLE s_hist (LIKE pack_monthly_histograms) ON COMMIT DROP;
ALTER TABLE s_hist DROP COLUMN source_id;
CREATE TEMP TABLE s_events (LIKE pack_events) ON COMMIT DROP;
ALTER TABLE s_events DROP COLUMN source_id;

\copy s_sites FROM '/seed/fleet_v2/sites.csv' WITH (FORMAT csv, HEADER true, NULL '')
\copy s_profiles FROM '/seed/fleet_v2/profiles.csv' WITH (FORMAT csv, HEADER true, NULL '')
\copy s_daily FROM PROGRAM 'gunzip -c /seed/fleet_v2/daily.csv.gz' WITH (FORMAT csv, HEADER true, NULL '')
\copy s_hist FROM PROGRAM 'gunzip -c /seed/fleet_v2/histograms.csv.gz' WITH (FORMAT csv, HEADER true, NULL '')
\copy s_events FROM PROGRAM 'gunzip -c /seed/fleet_v2/events.csv.gz' WITH (FORMAT csv, HEADER true, NULL '')

-- Seed identities must agree with the database identities.
DO $$ BEGIN
 IF EXISTS (SELECT FROM s_profiles p LEFT JOIN batteries b USING (battery_id)
            WHERE b.battery_id IS NULL OR b.chemistry <> p.chemistry OR b.rated_kwh <> p.rated_kwh) THEN
  RAISE EXCEPTION 'Fleet seed identities disagree with batteries table';
 END IF;
END $$;

INSERT INTO fleet_sites SELECT *, 'demo-fleet-v2' FROM s_sites;
INSERT INTO pack_profiles SELECT battery_id, site_id, commissioned_on, shifts, life_multiplier, opportunity_propensity,
 efc_before_window, 'demo-fleet-v2' FROM s_profiles;
INSERT INTO pack_daily SELECT *, 'demo-fleet-v2' FROM s_daily;
INSERT INTO pack_monthly_histograms SELECT *, 'demo-fleet-v2' FROM s_hist;
INSERT INTO pack_events SELECT *, 'demo-fleet-v2' FROM s_events;

INSERT INTO schema_migrations(version) VALUES ('005_fleet_history') ON CONFLICT DO NOTHING;
COMMIT;
